using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class GangsterNeonCityVerify{
const string D="Assets/Scenes/Oasis/GangsterNeonWallArt/",R="FinalEnvironmentRoadReview/GangsterNeonCity";
[Serializable]class Point{public float x,y;}[Serializable]class Outline{public int index;public float cx,cy,size;public Point[] points;}[Serializable]class Outlines{public Outline[] art;}
class Site{public string owner;public int art;public Vector3 p,n,camera;public float w,h;}
static GangsterNeonCityVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("GangsterNeonCityVerify.request"))return;File.Delete("GangsterNeonCityVerify.request");try{Run();}catch(Exception e){File.WriteAllText(R+"Verified.txt",e.ToString());Debug.LogException(e);}}
static void Run(){
var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Gangster Neon Road Facing Wall Art");
// Use the actual alpha-connected artwork outlines for UVs; the AI sheet has slightly uneven gutters.
// This isolates all 36 designs without modifying the approved PNG or creating per-design textures.
var outlines=JsonUtility.FromJson<Outlines>(File.ReadAllText(D+"Atlas Mesh Outlines.json"));var meshes=AssetDatabase.FindAssets("t:Mesh",new[]{D+"Meshes"}).Select(g=>AssetDatabase.LoadAssetAtPath<Mesh>(AssetDatabase.GUIDToAssetPath(g))).OrderBy(m=>m.name).ToArray();if(meshes.Length!=36||outlines.art.Length!=36)throw new Exception("Expected exactly 36 reusable meshes");
foreach(var a in outlines.art){var mesh=meshes[a.index];var points=a.points.Select(p=>new Vector3(-(p.x-a.cx)/a.size,-(p.y-a.cy)/a.size,0)).ToArray();var uv=a.points.Select(p=>new Vector2(p.x/1254f,1-p.y/1254f)).ToArray();var ids=new List<int>();for(int k=1;k<points.Length-1;k++)ids.AddRange(new[]{0,k,k+1});mesh.Clear();mesh.vertices=points;mesh.normals=Enumerable.Repeat(Vector3.forward,points.Length).ToArray();mesh.uv=uv;mesh.SetTriangles(ids,0);mesh.RecalculateBounds();EditorUtility.SetDirty(mesh);}
var fs=root.GetComponentsInChildren<MeshFilter>(true);foreach(var f in fs){var mesh=f.sharedMesh;f.sharedMesh=null;f.sharedMesh=mesh;var lod=f.GetComponent<LODGroup>();lod.RecalculateBounds();lod.size=1.25f;PrefabUtility.RecordPrefabInstancePropertyModifications(lod);}
AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);
var sites=File.ReadAllLines(R+"Placements.csv").Skip(1).Select(line=>{var a=line.Split(',');return new Site{owner=a[0],p=new Vector3(float.Parse(a[1]),float.Parse(a[2]),float.Parse(a[3])),n=new Vector3(float.Parse(a[4]),0,float.Parse(a[5])),w=float.Parse(a[6]),h=float.Parse(a[7]),art=int.Parse(a[8]),camera=new Vector3(float.Parse(a[9]),float.Parse(a[10]),float.Parse(a[11]))};}).ToArray();
var chosen=new List<Site>();foreach(var target in new[]{new Vector3(-440,32,-400),new Vector3(-110,32,-230),new Vector3(200,32,240),new Vector3(550,32,350),new Vector3(0,32,450),new Vector3(400,32,-300)}){var s=sites.Where(s=>!chosen.Contains(s)&&s.h>2.5f).OrderBy(s=>Vector3.Distance(s.p,target)).First();chosen.Add(s);}chosen.Add(sites.Where(s=>s.art>=31&&s.h>3).OrderByDescending(s=>s.h).First());chosen.Add(sites.Where(s=>s.h<2.1f).OrderByDescending(s=>s.w).First());
var ctrl=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);
try{ctrl.ApplyDay();for(int i=0;i<chosen.Count;i++){var s=chosen[i];var direction=(s.camera-s.p).normalized;float distance=Mathf.Min(Vector3.Distance(s.camera,s.p),Mathf.Max(13,s.w*2.5f));capture.Invoke(null,new object[]{scene,s.p+direction*distance,s.p,"Gangster-Neon-City-Day-"+(i+1)});}ctrl.ApplyNight();foreach(int i in new[]{1,6}){var s=chosen[i];var dir=(s.camera-s.p).normalized;float distance=Mathf.Min(Vector3.Distance(s.camera,s.p),Mathf.Max(13,s.w*2.5f));capture.Invoke(null,new object[]{scene,s.p+dir*distance,s.p,"Gangster-Neon-City-Night-"+(i+1)});}}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();}
var mats=root.GetComponentsInChildren<Renderer>().Select(r=>r.sharedMaterial).Distinct().ToArray();var paths=fs.Select(f=>PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(f.gameObject)).Distinct().ToArray();bool linked=fs.All(f=>PrefabUtility.IsPartOfPrefabInstance(f)&&PrefabUtility.GetCorrespondingObjectFromSource(f).sharedMesh==f.sharedMesh);if(!linked||paths.Length!=36||mats.Length!=1||!mats[0].enableInstancing)throw new Exception("Prefab sharing/instancing verification failed");
File.WriteAllText(R+"Verified.txt","SUCCESS instances="+fs.Length+" building groups="+root.transform.childCount+" unique meshes="+meshes.Length+" linked source prefab assets="+paths.Length+" all prefab meshes shared="+linked+" total placed triangles="+fs.Sum(f=>f.sharedMesh.triangles.Length/3)+" GPU instancing enabled="+mats[0].enableInstancing+" materials="+mats.Length+" new Lights="+root.GetComponentsInChildren<Light>(true).Length+" colliders="+root.GetComponentsInChildren<Collider>(true).Length+" shader errors="+mats.Any(m=>ShaderUtil.ShaderHasError(m.shader))+". Approved transparent atlas retained unchanged; silhouette mesh UVs isolate the 36 artwork pieces; native buildings unchanged. Eight daytime district/low-wall views and two nighttime views captured.\n"+string.Join("\n",chosen.Select((s,i)=>(i+1)+": "+s.owner+" art="+s.art+" at "+s.p)));
}
}
